<script setup>
import { computed, ref } from 'vue'
import { state, changeHours } from '../composables/useMonitor.js'
import { t, themeOptions, language } from '../composables/useTheme.js'
import { favorite, toggleFavorite } from '../composables/usePreferences.js'
import { HOURS, probes, probeLabel, probeText, present, bytes, percent, gpuInfo, online, timestamp } from '../utils/metrics.js'
import { osIcon, validRegion, uptimeDays, traffic, loadValues, probeTone } from '../utils/display.js'
import MetricBar from '../components/MetricBar.vue'
import HistoryChart from '../components/HistoryChart.vue'
import Icon from '../components/Icon.vue'
const server = computed(() => state.detail), site = computed(() => state.sites[state.page?.site || 0])
const probeMode = ref('ping'), hiddenProbes = ref([])
const numeric = key => state.rows.map(row => row[key] === null || row[key] === false || row[key] === undefined ? row[key] : Number(row[key]))
const times = computed(() => state.rows.map(row => row.timestamp ?? row.last_updated))
const rangeLabel = hours => hours === 0.167 ? '10 min' : hours === 0.5 ? '30 min' : hours < 24 ? `${hours} h` : `${hours / 24} d`
const transfer = computed(() => traffic(server.value || {}))
const load = computed(() => loadValues(server.value?.load_avg).map(value => value.toFixed(2)).join(' · '))
const charts = computed(() => {
  const current = server.value || {}
  const list = [
    { title: t('cpuAndLoad'), icon: 'cpu', summary: `${Number(current.cpu || 0).toFixed(1)}%`, unit: '%', max: Math.max(10, Math.ceil(Math.max(0, ...numeric('cpu').filter(value => typeof value === 'number')) / 10) * 10), series: [{ label: 'CPU', values: numeric('cpu') }, ...(state.rows.some(row => loadValues(row.load_avg).length) ? [{ label: t('load'), values: state.rows.map(row => loadValues(row.load_avg)[0]), right: true, color: '#91a4b9' }] : [])] },
    { title: t('memorySwap'), icon: 'memory', summary: `${bytes(Number(current.ram_used) * 1048576)} · ${bytes(Number(current.ram_total) * 1048576)}`, unit: 'bytes', series: [{ label: 'RAM', values: numeric('ram_used').map(value => typeof value === 'number' ? value * 1048576 : value) }, { label: t('ramTotal'), values: numeric('ram_total').map(value => typeof value === 'number' ? value * 1048576 : value), dashed: true }, ...(Number(current.swap_total) > 0 ? [{ label: 'Swap', values: numeric('swap_used').map(value => typeof value === 'number' ? value * 1048576 : value), color: '#7f90a8' }, { label: t('swapTotal'), values: numeric('swap_total').map(value => typeof value === 'number' ? value * 1048576 : value), dashed: true, color: '#c2cddd' }] : [])] },
    { title: t('disk'), icon: 'disk', summary: `${bytes(Number(current.disk_used) * 1048576)} · ${bytes(Number(current.disk_total) * 1048576)}`, unit: 'bytes', series: [{ label: t('diskUsed'), values: numeric('disk_used').map(value => typeof value === 'number' ? value * 1048576 : value) }, { label: t('diskTotal'), values: numeric('disk_total').map(value => typeof value === 'number' ? value * 1048576 : value), dashed: true }] }
  ]
  if (themeOptions.value.show_network !== false) list.push({ title: t('realtimeNetwork'), icon: 'network', summary: `↑ ${bytes(current.net_out_speed)}/s · ↓ ${bytes(current.net_in_speed)}/s`, unit: 'bytes', series: [{ label: `${t('download')} /s`, values: numeric('net_in_speed') }, { label: `${t('upload')} /s`, values: numeric('net_out_speed'), color: '#7d96b4' }] })
  if (present(current.tcp_conn) || present(current.udp_conn)) list.push({ title: t('connections'), icon: 'traffic', summary: `TCP: ${current.tcp_conn ?? '—'} · UDP: ${current.udp_conn ?? '—'}`, series: [{ label: 'TCP', values: numeric('tcp_conn') }, { label: 'UDP', values: numeric('udp_conn') }] })
  if (present(current.processes)) list.push({ title: t('processes'), icon: 'pulse', summary: String(current.processes), series: [{ label: t('processes'), values: numeric('processes') }] })
  if (current.disk && typeof current.disk === 'object') list.push({ title: 'Disk IO', icon: 'disk', summary: `R ${bytes(current.disk.read_bps)}/s · W ${bytes(current.disk.write_bps)}/s`, unit: 'bytes', series: ['read_bps', 'write_bps'].map((field, index) => ({ label: index ? 'W /s' : 'R /s', values: state.rows.map(row => { let disk = row.disk; if (typeof disk === 'string') { try { disk = JSON.parse(disk) } catch { disk = null } } return disk?.[field] }) })) })
  for (const gpu of gpuInfo(current.gpu_info)) list.push({ title: gpu.name || 'GPU', icon: 'cpu', summary: `${gpu.info ?? '—'}%`, unit: '%', max: 100, series: [{ label: 'GPU', values: state.rows.map(row => { const value = gpuInfo(row.gpu_info).find(item => String(item.id) === String(gpu.id))?.info; return value === null || value === undefined ? undefined : Number(value) }) }] })
  return list
})
const probeKeys = computed(() => probes.filter(key => present(server.value?.[`ping_${key}`]) || present(server.value?.[`loss_${key}`]) || state.rows.some(row => present(row[`ping_${key}`]) || present(row[`loss_${key}`]))))
const probeSeries = computed(() => probeKeys.value.filter(key => !hiddenProbes.value.includes(key)).map(key => ({ label: probeLabel(site.value.config, key), values: numeric(`${probeMode.value}_${key}`) })))
function toggleProbe(key) { hiddenProbes.value = hiddenProbes.value.includes(key) ? hiddenProbes.value.filter(value => value !== key) : [...hiddenProbes.value, key] }
const coverage = computed(() => {
  const end = Date.now(), start = end - state.hours * 3600000, duration = (end - start) / 28
  return Array.from({ length: 28 }, (_, index) => { const begin = start + duration * index, finish = begin + duration; return { present: state.rows.some(row => { const ts = timestamp(row.timestamp ?? row.last_updated); return ts >= begin && ts < finish }), label: `${new Date(begin).toLocaleTimeString()} – ${new Date(finish).toLocaleTimeString()}` } })
})
const updated = computed(() => timestamp(server.value?.last_updated) ? new Date(timestamp(server.value.last_updated)).toLocaleString(language.value) : '—')
</script>
<template>
  <p v-if="state.loading && !server" class="empty">{{ t('loading') }}</p>
  <template v-if="server">
    <div class="detail-title"><RouterLink class="back-link" to="/" :aria-label="t('back')"><Icon name="back" :size="20"/></RouterLink><img v-if="osIcon(server.os)" class="os-icon" :src="`${site.base}/os-icons/${osIcon(server.os)}`" :alt="server.os"><h1>{{ server.name || server.id }}</h1><img v-if="validRegion(server.region)" class="flag-icon" :src="`${site.base}/flags/${server.region.toLowerCase()}.svg`" :alt="server.region"><span class="detail-status"><span class="state-dot" :class="{ offline: !online(server) }"></span>{{ t(online(server) ? 'online' : 'offline') }}</span><button class="favorite-button" :class="{ selected: favorite(state.page.site || 0, server.id) }" :aria-label="t('favorite')" @click="toggleFavorite(state.page.site || 0, server.id)"><Icon name="star"/></button></div>
    <div class="detail-metrics"><div class="panel"><MetricBar label="CPU" :value="Number(server.cpu)" :detail="`${t('load')} ${load || '—'}`"/></div><div class="panel"><MetricBar :label="t('ram')" :value="percent(server.ram_used, server.ram_total)" :detail="`${bytes(Number(server.ram_used) * 1048576)} / ${bytes(Number(server.ram_total) * 1048576)}`"/></div><div class="panel"><MetricBar :label="t('disk')" :value="percent(server.disk_used, server.disk_total)" :detail="`${bytes(Number(server.disk_used) * 1048576)} / ${bytes(Number(server.disk_total) * 1048576)}`"/></div><div class="panel"><MetricBar :label="t('transfer')" :value="transfer.percentage" :unlimited="!transfer.limit" :detail="transfer.detail"/></div></div>
    <section class="device-panel panel"><h2><Icon name="server" :size="16"/>{{ t('deviceInfo') }}</h2><dl><div><dt><Icon name="cpu" :size="14"/>CPU</dt><dd>{{ server.cpu_info || '—' }}</dd></div><div><dt><Icon name="code" :size="14"/>{{ t('architecture') }}</dt><dd>{{ server.arch || '—' }}</dd></div><div><dt><Icon name="server" :size="14"/>{{ t('cores') }}</dt><dd>{{ server.cpu_cores || '—' }} vCPU</dd></div><div><dt><Icon name="disk" :size="14"/>{{ t('os') }}</dt><dd><img v-if="osIcon(server.os)" class="os-icon" :src="`${site.base}/os-icons/${osIcon(server.os)}`" alt="">{{ server.os || '—' }}</dd></div><div><dt><Icon name="code" :size="14"/>{{ t('kernel') }}</dt><dd>{{ server.kernel_version || '—' }}</dd></div><div><dt><Icon name="clock" :size="14"/>{{ t('uptime') }}</dt><dd>{{ uptimeDays(server.boot_time) === null ? '—' : `${uptimeDays(server.boot_time)} ${t('days')}` }}</dd></div><div><dt><Icon name="clock" :size="14"/>{{ t('updated') }}</dt><dd>{{ updated }}</dd></div></dl></section>
    <section class="coverage-panel panel"><div><h2><Icon name="calendar" :size="15"/>{{ t('sampleCoverage') }} <span :title="t('coverageHint')"><Icon name="info" :size="13"/></span></h2><span>{{ rangeLabel(state.hours) }}</span></div><div class="coverage-strip"><i v-for="(bucket, index) in coverage" :key="index" :class="{ measured: bucket.present }" :title="`${bucket.label} · ${t(bucket.present ? 'hasSample' : 'noSample')}`"></i></div><div class="coverage-legend"><span><i class="measured"></i>{{ t('hasSample') }}</span><span><i></i>{{ t('noSample') }}</span></div></section>
    <div class="range-toolbar"><div class="range-tabs"><button v-for="hours in [0.167, 1, 6, 12, 24, 168]" :key="hours" :class="{ active: state.hours === hours }" @click="hours !== state.hours && changeHours(hours)">{{ hours === 0.167 ? t('realtime') : rangeLabel(hours) }}</button></div><select :value="state.hours" @change="changeHours(Number($event.target.value))" :aria-label="t('history')"><option v-for="hours in HOURS" :key="hours" :value="hours">{{ rangeLabel(hours) }}</option></select></div>
    <p v-if="state.historyLoading" class="history-loading muted" role="status">{{ t('loading') }}</p>
    <div class="chart-grid"><HistoryChart v-for="chart in charts" :key="chart.title" v-bind="chart" :times="times"/></div>
    <section v-if="probeKeys.length" class="probes-section"><div class="range-toolbar"><div class="range-tabs"><button :class="{ active: probeMode === 'ping' }" @click="probeMode = 'ping'">{{ t('latency') }}</button><button :class="{ active: probeMode === 'loss' }" @click="probeMode = 'loss'">{{ t('loss') }}</button></div><span class="muted">{{ rangeLabel(state.hours) }} · {{ t('sharedHistory') }}</span></div><div class="probe-selectors"><button v-for="key in probeKeys" :key="key" :class="{ disabled: hiddenProbes.includes(key) }" :aria-pressed="!hiddenProbes.includes(key)" @click="toggleProbe(key)"><span>{{ probeLabel(site.config, key) }}</span><strong v-if="present(server[`ping_${key}`])" :class="probeTone(server[`ping_${key}`])">{{ probeText(server[`ping_${key}`], ' ms', t('timeout')) }}</strong><small v-if="present(server[`loss_${key}`])"> · {{ probeText(server[`loss_${key}`], '%', t('timeout')) }}</small></button></div><HistoryChart :title="t(probeMode === 'ping' ? 'latency' : 'loss')" icon="network" :series="probeSeries" :times="times" :unit="probeMode === 'ping' ? 'ms' : '%'" :max="probeMode === 'loss' ? 100 : undefined"/></section>
  </template>
</template>
